function normalizeShippingAddress(rawShipping) {
  if (!rawShipping) return null;

  // Step 1: Parse JSON string if needed
  let shipping = rawShipping;
  if (typeof rawShipping === 'string') {
    try {
      shipping = JSON.parse(rawShipping);
    } catch (e) {
      console.warn('Failed to parse shipping_address JSON string:', e.message);
      return null;
    }
  }

  // Step 2: Ensure it's an object
  if (typeof shipping !== 'object' || Array.isArray(shipping) || shipping === null) {
    return null;
  }

  // Step 3: Normalize field names - map legacy to expected format
  // Keep both formats for backward compatibility
  const normalized = { ...shipping };

  // Normalize address field
  if (normalized.address && !normalized.address_line_1) {
    normalized.address_line_1 = normalized.address;
  } else if (normalized.address_line_1 && !normalized.address) {
    normalized.address = normalized.address_line_1; // Keep legacy for compatibility
  }

  // Normalize state field
  if (normalized.state && !normalized.state_code) {
    normalized.state_code = normalized.state;
  } else if (normalized.state_code && !normalized.state) {
    normalized.state = normalized.state_code; // Keep legacy for compatibility
  }

  // Normalize zip/postal_code field
  if (normalized.zip && !normalized.postal_code) {
    normalized.postal_code = normalized.zip;
  } else if (normalized.postal_code && !normalized.zip) {
    normalized.zip = normalized.postal_code; // Keep legacy for compatibility
  }

  // Normalize address_line_2 (if present)
  if (normalized.address2 && !normalized.address_line_2) {
    normalized.address_line_2 = normalized.address2;
  } else if (normalized.address_line_2 && !normalized.address2) {
    normalized.address2 = normalized.address_line_2; // Keep legacy for compatibility
  }

  // Ensure name field exists (may be called recipient_name or name)
  if (normalized.recipient_name && !normalized.name) {
    normalized.name = normalized.recipient_name;
  }

  // D2C uses address_line1 (no underscore before 1)
  if (normalized.address_line1 && !normalized.address_line_1) {
    normalized.address_line_1 = normalized.address_line1;
  } else if (normalized.address_line_1 && !normalized.address_line1) {
