function trimKey(value) {
  return String(value || '').replace(/^\/+/, '').split('?')[0].split('#')[0];
}

function normalizeManifestReference(value) {
  const raw = value == null ? '' : String(value).trim();
  if (!raw) return { raw: '', key: '', directUrl: null };

  if (raw.startsWith('/api/manifests/')) {
    return { raw, key: trimKey(raw.split('/api/manifests/')[1] || ''), directUrl: `${backendBase}${raw}` };
  }
  if (raw.startsWith('/api/assets/')) {
    return { raw, key: trimKey(raw.split('/api/assets/')[1] || ''), directUrl: `${backendBase}${raw}` };
  }
  if (raw.includes('/api/manifests/')) {
    return { raw, key: trimKey(raw.split('/api/manifests/')[1] || ''), directUrl: raw };
  }
  if (raw.includes('/api/assets/')) {
    return { raw, key: trimKey(raw.split('/api/assets/')[1] || ''), directUrl: raw };
  }
  if (/^https?:\/\//i.test(raw)) {
    try {
      const url = new URL(raw);
      return { raw, key: trimKey(url.pathname), directUrl: raw };
    } catch {
      return { raw, key: '', directUrl: raw };
    }
  }

  return { raw, key: trimKey(raw), directUrl: null };
}

