  else if (normalized.address_line_2 && !normalized.address2) normalized.address2 = normalized.address_line_2;

  if (normalized.recipient_name && !normalized.name) normalized.name = normalized.recipient_name;

  if (normalized.address_line1 && !normalized.address_line_1) normalized.address_line_1 = normalized.address_line1;
  else if (normalized.address_line_1 && !normalized.address_line1) normalized.address_line1 = normalized.address_line_1;

  if (normalized.address_line2 && !normalized.address_line_2) normalized.address_line_2 = normalized.address_line2;
  else if (normalized.address_line_2 && !normalized.address_line2) normalized.address_line2 = normalized.address_line_2;

  if (!normalized.address_line_1) {
    normalized.address_line_1 = normalized.address_line1 || normalized.address || '';
  }

  const rawPhone = normalized.phone_number || normalized.phone;
  const cleanedPhone = cleanPhoneNumber(rawPhone);
  const phone_number = cleanedPhone || '+1-678-478-3477';
  normalized.phone_number = phone_number;
  if (!normalized.phone) normalized.phone = phone_number;

  return normalized;
}

function buildPreparedItem(row, rootHint = null) {
  const orderId = firstNonEmpty(row.orderId, row.order_id, row.amazon_order_id, row.amazonOrderId);
  if (!orderId) return null;

  const rootOrderId = firstNonEmpty(
    row.rootOrderId,
    row.root_order_id,
    deriveRoot(row.amazon_order_id || row.amazonOrderId || orderId),
    rootHint,
    deriveRoot(orderId),
    orderId,
  );
  const amazonOrderId = firstNonEmpty(
    row.amazonOrderId,
    row.amazon_order_id,
    row.rootOrderId,
    row.root_order_id,
    rootOrderId,
  );

  return {
    json: {
      orderId,
      rootOrderId,
      amazonOrderId,
      characterHash: firstNonEmpty(row.characterHash, row.character_hash),
      orderDbId: row.orderDbId != null ? row.orderDbId : row.id,
      workflow: '4',
      shipping_address: normalizeShippingAddress(row.shipping_address),
      manifest3Key: firstNonEmpty(row.manifest3Key, row.three_manifest_url, row.manifest3Url, `${prefix}/${orderId}/manifests/3-manifest.json`),
      oneManifestKey: firstNonEmpty(row.oneManifestKey, row.one_manifest_url, row.oneManifestUrl, `${prefix}/${orderId}/manifests/1-manifest.json`),
      ShipmentServiceLevelCategory: firstNonEmpty(row.ShipmentServiceLevelCategory, row.amazon_shipment_service_level),
      ShipServiceLevel: firstNonEmpty(row.ShipServiceLevel, row.amazon_shipment_service_level),
      shipping_tier: firstNonEmpty(row.shipping_tier, row.shippingTier),
    },
  };
}

function parseItemNumber(orderId) {
  const m = String(orderId || '').match(/-item-(\d+)$/);
  return m ? Number(m[1]) : Number.MAX_SAFE_INTEGER;
}

function attachSiblingClaimMetadata(items, rootId) {
  const claimOrderDbIds = [...new Set(
    items
      .map((item) => item?.json?.orderDbId)
      .filter((value) => value !== undefined && value !== null && String(value).trim() !== '')
      .map((value) => String(value).trim())
  )];
  const claimGroupSize = claimOrderDbIds.length;
  const claimStartedAt = new Date().toISOString();

  for (const item of items) {
    item.json._route = 'sibling';
    item.json.claimOrderDbIds = claimOrderDbIds;
    item.json.claimGroupSize = claimGroupSize;
    item.json.claimRootOrderId = rootId;
    item.json.claimStartedAt = claimStartedAt;
  }

  return items;
}

async function fetchSiblingRows(rootId) {
  return await this.helpers.request({
    method: 'GET',
    uri: `${supabaseUrl}/rest/v1/orders`,
    qs: {
      root_order_id: `eq.${rootId}`,
      select: 'id,orderId,root_order_id,amazon_order_id,character_hash,shipping_address,one_manifest_url,amazon_shipment_service_level,shipping_tier,execution_status,next_workflow'
    },
    headers: {
      apikey: supabaseKey,
      Authorization: `Bearer ${supabaseKey}`,
    },
    json: true,
  });
}

const items = $input.all();
if (!items || items.length === 0) return [];

const groups = new Map();
for (const item of items) {
  const prepared = buildPreparedItem(item.json || {});
  if (!prepared) continue;
  const rootId = firstNonEmpty(prepared.json.rootOrderId, deriveRoot(prepared.json.orderId), prepared.json.orderId);
  if (!groups.has(rootId)) groups.set(rootId, []);
  groups.get(rootId).push(prepared);
}

const output = [];
let heldGroups = 0;

for (const [rootId, group] of groups) {
  const preparedByOrderId = new Map();
  for (const item of group) {
    preparedByOrderId.set(item.json.orderId, item);
  }

  let siblingRows = null;
  try {
    siblingRows = await fetchSiblingRows.call(this, rootId);
  } catch (e) {
    console.warn(`Supabase sibling lookup failed for ${rootId}: ${e.message}`);
  }

  if (Array.isArray(siblingRows) && siblingRows.length > 0) {
    const childRows = siblingRows.filter(row => {
      const orderId = firstNonEmpty(row.orderId, row.order_id, row.amazon_order_id, row.amazonOrderId);
      return orderId && orderId !== rootId;
    });

    if (childRows.length > 1) {
      const readyRows = childRows.filter(row => {
        const executionStatus = String(row.execution_status || '').trim();
        const nextWorkflow = String(row.next_workflow || '').trim();
        return executionStatus === 'ready_for_processing' && (nextWorkflow === '4' || nextWorkflow === '4-aggregate');
      });

      if (readyRows.length === childRows.length) {
        for (const row of readyRows) {
          const built = buildPreparedItem(row, rootId);
          if (!built) continue;
          const existing = preparedByOrderId.get(built.json.orderId);
          preparedByOrderId.set(built.json.orderId, existing ? { json: { ...built.json, ...existing.json } } : built);
        }

        const completeGroup = [...preparedByOrderId.values()].sort((a, b) => parseItemNumber(a.json.orderId) - parseItemNumber(b.json.orderId));
        if (completeGroup.length === childRows.length) {
          const claimReadyGroup = attachSiblingClaimMetadata(completeGroup, rootId);
          for (const item of claimReadyGroup) {
            output.push(item);
          }
          console.log(`Sibling group ${rootId}: hydrated ${claimReadyGroup.length}/${childRows.length} ready items -> w4.1`);
          continue;
        }

        heldGroups += 1;
        console.log(`HOLD order ${group[0].json.orderId} (rootId=${rootId}): expected ${childRows.length} siblings, hydrated ${completeGroup.length}`);
        continue;
      }

      const blocked = childRows
        .map(row => {
          const orderId = firstNonEmpty(row.orderId, row.order_id, row.amazon_order_id, row.amazonOrderId) || '(unknown)';
          const executionStatus = String(row.execution_status || 'null');
          const nextWorkflow = String(row.next_workflow || 'null');
          return `${orderId}[status=${executionStatus},next=${nextWorkflow}]`;
        })
        .join(', ');
      heldGroups += 1;
      console.log(`HOLD order ${group[0].json.orderId} (rootId=${rootId}): sibling group incomplete/not ready -> ${blocked}`);
      continue;
    }
  }

  if (preparedByOrderId.size >= 2) {
    const completeGroup = [...preparedByOrderId.values()].sort((a, b) => parseItemNumber(a.json.orderId) - parseItemNumber(b.json.orderId));
    const claimReadyGroup = attachSiblingClaimMetadata(completeGroup, rootId);
    for (const item of claimReadyGroup) {
      output.push(item);
    }
    console.log(`Sibling group ${rootId}: ${claimReadyGroup.length} batch items -> w4.1`);
    continue;
  }

  const single = [...preparedByOrderId.values()][0];
  if (!single) continue;
  single.json._route = 'single';
  single.json.claimStartedAt = new Date().toISOString();
  output.push(single);
  console.log(`Single order ${single.json.orderId} (rootId=${rootId}) -> w4`);
}

console.log(`Classify result: ${output.length} forwarded, ${heldGroups} sibling group(s) held`);
return output;

// Bundle sibling-tagged items into strict { siblingGroup: [...] } payloads for w4.1.
const items = $input.all();
if (!items || items.length === 0) return [];

function firstNonEmpty(...vals) {
  for (const v of vals) {
    if (v === undefined || v === null) continue;
    if (typeof v === 'string') {
      const s = v.trim();
      if (s !== '') return s;
    } else {
      return v;
    }
  }
}

function deriveRoot(id) {
  if (!id) return id;
  const m = String(id).match(/^(.+?)-item-/);
  return m ? m[1] : id;
}

const groups = new Map();
for (const item of items) {
  const j = item.json || {};
  const orderId = firstNonEmpty(j.orderId, j.order_id, j.amazon_order_id, j.amazonOrderId);
  if (!orderId) continue;

  // Always group by shared root, never by item-specific rootOrderId.
  const rootId = firstNonEmpty(deriveRoot(orderId), deriveRoot(j.amazon_order_id), deriveRoot(j.amazonOrderId), j.rootOrderId, j.root_order_id, orderId);
  if (!groups.has(rootId)) groups.set(rootId, []);

  const manifest3Key = firstNonEmpty(
    j.manifest3Key,
    j.three_manifest_url,
    j.manifest3Url,
    j.manifestUrl,
    `book-mvp-simple-adventure/orders/${orderId}/manifests/3-manifest.json`
  );
  const oneManifestUrl = firstNonEmpty(j.oneManifestUrl, j.one_manifest_url, j.oneManifestKey);

  groups.get(rootId).push({
    ...j,
    orderId,
    rootOrderId: firstNonEmpty(deriveRoot(orderId), j.rootOrderId, j.root_order_id, rootId),
    manifest3Key,
    one_manifest_url: oneManifestUrl || null
  });
}

const output = [];
for (const [rootId, siblings] of groups) {
  output.push({ json: { siblingGroup: siblings } });
  console.log(`Bundled ${siblings.length} siblings for rootId=${rootId}`);
}

return output;
